var text = String(input.h || "");
var WORD = /[\p{L}\p{N}]+(?:['\u2019\u02BC-][\p{L}\p{N}]+)*/gu;
var START = /(?:^|[.!?\u2026\n])[\s"'\u00AB\u00BB\u201C\u201D\u201E\u2018\u2019*_(\[\u2014\u2013-]*$/;
var rows = text.split(/\n\n(?=[^\n:]{1,60}: )/).map(function (r) { return r.replace(/^[^\n:]{1,60}: /, ""); }).slice(-6);

function tokens(s) {
  var out = [];
  var m;
  var prev = 0;
  WORD.lastIndex = 0;
  while ((m = WORD.exec(s)) !== null) {
    var w = m[0];
    var brk = /[.!?…\n;:]/.test(s.slice(prev, m.index));
    prev = m.index + w.length;
    var cap = w.charAt(0) !== w.charAt(0).toLowerCase();
    var first = START.test(s.slice(Math.max(0, m.index - 12), m.index));
    out.push({ low: w.toLowerCase(), len: w.length, name: cap && !first, brk: brk, at: m.index, end: m.index + w.length });
  }
  return out;
}

var grams = new Map();
var all = [];
for (var r = 0; r < rows.length; r++) {
  var t = tokens(rows[r]);
  all.push(t);
  for (var n = 3; n <= 5; n++) {
    for (var i = 0; i + n <= t.length; i++) {
      var key = t[i].low;
      var cut = false;
      for (var k = 1; k < n; k++) { if (t[i + k].brk) { cut = true; break; } key += " " + t[i + k].low; }
      if (cut) continue;
      var g = grams.get(key);
      if (!g) { g = { reps: new Set(), r: r, i: i, n: n }; grams.set(key, g); }
      g.reps.add(r);
    }
  }
}

var cands = [];
grams.forEach(function (g, key) {
  if (g.reps.size < 2) return;
  var t = all[g.r].slice(g.i, g.i + g.n);
  var letters = 0;
  var content = false;
  for (var j = 0; j < t.length; j++) {
    letters += t[j].len;
    if (!t[j].name && t[j].len >= 4) content = true;
  }
  if (!content || letters < 12) return;
  cands.push({ key: key, n: g.n, reps: g.reps.size, letters: letters, shown: rows[g.r].slice(t[0].at, t[t.length - 1].end) });
});
cands.sort(function (a, b) { return b.n - a.n || b.reps - a.reps || b.letters - a.letters; });
var kept = [];
for (var c = 0; c < cands.length && kept.length < 5; c++) {
  var w = cands[c].key.split(" ");
  var clash = false;
  for (var q = 0; q < kept.length && !clash; q++) {
    var hay = " " + kept[q].key + " ";
    for (var p = 0; p + 1 < w.length; p++) {
      if (w[p].length < 4 && w[p + 1].length < 4) continue;
      if (hay.indexOf(" " + w[p] + " " + w[p + 1] + " ") >= 0) { clash = true; break; }
    }
  }
  if (!clash) kept.push(cands[c]);
}
kept.sort(function (a, b) { return b.letters - a.letters; });

var opens = new Map();
for (var r2 = 0; r2 < rows.length; r2++) {
  var sentences = rows[r2].split(/(?<=[.!?\u2026])\s+|\n+/);
  for (var s = 0; s < sentences.length; s++) {
    var t2 = tokens(sentences[s]);
    if (t2.length < 3) continue;
    var okey = t2[0].low + " " + t2[1].low;
    var o = opens.get(okey);
    if (!o) { o = { n: 0, letters: t2[0].len + t2[1].len, shown: sentences[s].slice(t2[0].at, t2[1].end) }; opens.set(okey, o); }
    o.n++;
  }
}
var openers = [];
opens.forEach(function (o) { if (o.n >= 3 && o.letters >= 8) openers.push(o); });
openers.sort(function (a, b) { return b.n - a.n; });
openers = openers.slice(0, 2);

if (!kept.length && !openers.length) return {};
var parts = [];
if (kept.length) parts.push("Do not reuse these phrases from earlier replies: " + kept.map(function (x) { return '"' + x.shown + '"'; }).join("; ") + ".");
if (openers.length) parts.push("Do not open sentences with " + openers.map(function (x) { return '"' + x.shown + '..."'; }).join(" or ") + " again.");
parts.push("Say it in fresh words.");
return { text: parts.join(" ") };
